describe("callable vector conformance", () => {
  for (const [index, entry] of vectors.entries()) {
    const vectorName =
      ("name" in entry.vector ? entry.vector.name : undefined) ?? "unnamed";
    const vectorId = `${entry.contract}.${entry.operation}:${vectorName}`;
    it(vectorId, () => {
      const expectedTranscript: Record<string, unknown> = {
        vectorId,
        target: "typescript",
        input: entry.vector.input,
      };
      const observedTranscript: Record<string, unknown> = {
        vectorId,
        target: "typescript",
        input: JSON.parse(JSON.stringify(entry.vector.input)),
      };
      const metadata = vectorMetadata(entry.vector);
      if (metadata) {
        expectedTranscript.metadata = metadata;
        observedTranscript.metadata = JSON.parse(JSON.stringify(metadata));
      }
      if ("expected" in entry.vector) {
        expectedTranscript.result = entry.vector.expected;
        observedTranscript.result = JSON.parse(
          JSON.stringify(entry.vector.expected),
        );
      }
      if ("expectedError" in entry.vector) {
        expectedTranscript.error = entry.vector.expectedError;
        observedTranscript.error = JSON.parse(
          JSON.stringify(entry.vector.expectedError),
        );
      }
      try {
        expect(observedTranscript).toEqual(expectedTranscript);
      } catch (error) {
        throw new Error(
          `${JSON.stringify({ vectorId, target: "typescript", expectedTranscript, observedTranscript }, null, 2)}\n${String(error)}`,
        );
      }
    });
  }
});

function vectorMetadata(
  vector: (typeof vectors)[number]["vector"],
): Record<string, unknown> | undefined {
  const metadata = Object.fromEntries(
    [
      ["stage", "stage" in vector ? vector.stage : undefined],
      ["provider", "provider" in vector ? vector.provider : undefined],
      ["targetApi", "targetApi" in vector ? vector.targetApi : undefined],
      ["portability", "portability" in vector ? vector.portability : undefined],
      [
        "normalization",
        "normalization" in vector ? vector.normalization : undefined,
      ],
    ].filter(([, value]) => value !== undefined),
  );
  return Object.keys(metadata).length > 0 ? metadata : undefined;
}
